/* From Uiverse.io by simontheonlyone - Tags: exotic, button, active, weather, animated, focus, night, day */
.__UIV_SCOPE__ button {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 11em;
  height: 4em;
  border: none;
  border-radius: 2.1em;
  background-color: rgb(23, 56, 128);
  color: whitesmoke;
  font-weight: bold;
  font-size: 17px;
  text-align: center;
  cursor: pointer;
  transition: background-color .2s linear 1.1s,
  color .2s linear 1.1s;
}

.__UIV_SCOPE__ button:active,
.__UIV_SCOPE__ button:focus {
  background: rgb(254, 138, 30);
}

.__UIV_SCOPE__ button .day {
  position: absolute;
  opacity: 0;
  transition: all .2s ease 1.1s;
}

.__UIV_SCOPE__ button .night {
  transition: all .2s ease 1.1s;
}

.__UIV_SCOPE__ button:active .night,
.__UIV_SCOPE__ button:focus .night {
  color: transparent;
}

.__UIV_SCOPE__ button:active .day,
.__UIV_SCOPE__ button:focus .day {
  opacity: 1;
}
/* mini cloud */
.__UIV_SCOPE__ .mini-cloud {
  content: '';
  position: absolute;
  inset: -26% 62%;
  scale: 2;
  opacity: 1;
  color: rgb(150, 150, 150);
  transform: rotate(3deg);
  transition: scale .4s ease .3s,
  opacity .4s ease 1.3s;
  pointer-events: none;
}
/* lightning */
.__UIV_SCOPE__ .lightning {
  content: '';
  position: absolute;
  inset: -4% 62%;
  scale: 1.3;
  transform: rotate(15deg);
  transition: all .4s ease .2s,
  opacity .4s ease 1.5s;
  pointer-events: none;
}
/* stars */
.__UIV_SCOPE__ .stars {
  content: '';
  position: absolute;
  pointer-events: none;
}

.__UIV_SCOPE__ .star1 {
  inset: 15% 10%;
  scale: 1.2;
  opacity: 1;
  transition: all .4s ease .4s,
  opacity .4s ease 1.6s;
}

.__UIV_SCOPE__ .star2 {
  inset: 45% 80%;
  scale: 1;
  opacity: 1;
  transition: all .4s ease .5s,
  opacity .4s ease 1.7s;
}
/* cloud */
.__UIV_SCOPE__ .cloud {
  content: '';
  position: absolute;
  pointer-events: none;
  border: none;
}

.__UIV_SCOPE__ .left-side {
  width: 4.4em;
  height: 4.4em;
  bottom: 0;
  left: -.8em;
  scale: 1;
  border-radius: 50%;
  z-index: -5;
  background-color: rgb(15, 39, 91);
  transition: all .6s ease .6s;
}

.__UIV_SCOPE__ .left-side1 {
  width: 4.4em;
  height: 4.4em;
  bottom: 0;
  left: -.4em;
  scale: .95;
  border-radius: 50%;
  z-index: -4;
  background-color: rgb(23, 56, 128);
  transition: all .5s ease .5s;
}

.__UIV_SCOPE__ .middle-side {
  width: 9em;
  height: 8.3em;
  bottom: 0;
  left: 1em;
  border-radius: 50%;
  scale: 1;
  z-index: -7;
  background-color: rgb(15, 39, 91);
  transition: scale, bottom, .4s ease .8s, opactiy .2s linear .8s;
}

.__UIV_SCOPE__ .middle-side1 {
  width: 9em;
  height: 8.3em;
  bottom: -2px;
  left: 1.1em;
  scale: .95;
  z-index: -6;
  border-radius: 50%;
  background-color: rgb(23, 56, 128);
  transition: scale, bottom, .4s ease .75s, opactiy .2s linear .75s;
}

.__UIV_SCOPE__ .right-side {
  width: 5.5em;
  height: 5.5em;
  bottom: -1px;
  right: -1.4em;
  border-radius: 50%;
  scale: .98;
  z-index: -5;
  background-color: rgb(15, 39, 91);
  transition: all .6s ease .7s;
}

.__UIV_SCOPE__ .right-side1 {
  width: 5.5em;
  height: 5.5em;
  bottom: 0;
  right: -1.05em;
  border-radius: 50%;
  scale: .92;
  z-index: -4;
  background-color: rgb(23, 56, 128);
  transition: all .5s ease .6s;
}
/* night active animation */
.__UIV_SCOPE__ button:active .star1,
.__UIV_SCOPE__ button:focus .star1 {
  scale: 0;
  opacity: 0;
}

.__UIV_SCOPE__ button:active .star2,
.__UIV_SCOPE__ button:focus .star2 {
  scale: 0;
  opacity: 0;
}

.__UIV_SCOPE__ button:active .mini-cloud,
.__UIV_SCOPE__ button:focus .mini-cloud {
  scale: 0;
  opacity: 0;
}

.__UIV_SCOPE__ button:active .lightning,
.__UIV_SCOPE__ button:focus .lightning {
  scale: 0;
  opacity: 0;
}

.__UIV_SCOPE__ button:active .left-side,
.__UIV_SCOPE__ button:focus .left-side,
.__UIV_SCOPE__ button:active .left-side1,
.__UIV_SCOPE__ button:focus .left-side1 {
  scale: 0;
  opacity: 0;
}

.__UIV_SCOPE__ button:active .middle-side,
.__UIV_SCOPE__ button:focus .middle-side,
.__UIV_SCOPE__ button:active .middle-side1,
.__UIV_SCOPE__ button:focus .middle-side1 {
  scale: 0;
  opacity: 0;
  bottom: -40%;
}

.__UIV_SCOPE__ button:active .right-side,
.__UIV_SCOPE__ button:focus .right-side,
.__UIV_SCOPE__ button:active .right-side1,
.__UIV_SCOPE__ button:focus .right-side1 {
  scale: 0;
  opacity: 0;
}
/* sun */
.__UIV_SCOPE__ .sun {
  position: absolute;
  top: -100%;
  left: -4%;
  width: 12em;
  height: 12em;
  background-color: #fe8a1e;
  /* background: linear-gradient(blue, red); */
  border: none;
  border-radius: 50%;
  scale: 0;
  opacity: 0;
  pointer-events: none;
  z-index: -10;
  pointer-events: none;
  transition: scale .3s ease 1.4s,
      opacity .7s ease;
}

.__UIV_SCOPE__ button:active .sun,
.__UIV_SCOPE__ button:focus .sun {
  scale: .95;
  opacity: 1;
}
/* sunshine */
.__UIV_SCOPE__ .sunshine {
  content: '';
  position: absolute;
  width: 18.5em;
  height: 18.5em;
  scale: 0;
  opacity: 0;
  z-index: -9;
  pointer-events: none;
  animation: spin 15s infinite linear;
  transition: scale .3s ease 1.5s,
  opacity .1s ease;
}

.__UIV_SCOPE__ button:active .sunshine,
.__UIV_SCOPE__ button:focus .sunshine {
  scale: 1;
  opacity: 1;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.__UIV_SCOPE__ .cloudflare {
  position: absolute;
  opacity: 0;
  scale: 0;
  pointer-events: none;
}

.__UIV_SCOPE__ .cloudflare-one {
  inset: 5% 77%;
  width: 25px;
  height: 25px;
  transition: scale .3s ease 1.6s,
  opacity .3s ease;
}

.__UIV_SCOPE__ .cloudflare-two {
  inset: -43% 45%;
  width: 32px;
  height: 32px;
  transition: scale .3s ease 1.8s,
  opacity .3s ease;
}

.__UIV_SCOPE__ .cloudflare-three {
  inset: -10% 17%;
  width: 23px;
  height: 23px;
  transition: scale .3s ease 1.7s,
  opacity .3s ease;
}

.__UIV_SCOPE__ button:active .cloudflare,
.__UIV_SCOPE__ button:focus .cloudflare {
  scale: 1;
  opacity: 1;
}
